#!/usr/bin/env bash
set -Eeuo pipefail

SID="${1:-25}"
QUOTA="${2:-12}"
DIFF="${3:-4}"
SITE_ROOT="${4:-${OLDZ_SITE_ROOT:-}}"
STAMP="$(date +%Y%m%d-%H%M%S)"
UNIT="hyper-cs16@${SID}.service"
CTL="/root/hyper-hosting-panel/cs16-panel/bin/hyper-cs16-ctl"
BACKUP="/root/oldz-delux-identity-v8-${SID}-${STAMP}"
WORK="/tmp/oldz-delux-identity-v8-${SID}-${STAMP}"

fail() { echo "[ERROR] $*"; exit 1; }

if [[ "${EUID}" -ne 0 ]]; then fail "Run as root"; fi
mkdir -p "$BACKUP" "$WORK"

echo "================================================================"
echo " OLD ZOMBIE DELUX + IDENTITY v8"
echo " Server: #${SID}"
echo " Backup: ${BACKUP}"
echo "================================================================"

CFG="/var/lib/hyper-cs16/servers/${SID}.json"
LEGACY_CFG="/etc/hyper-cs16/servers/${SID}.json"
json_get() {
  python3 - "$1" "$2" <<'PYJ'
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding='utf-8'))
    print(d.get(sys.argv[2],"") or "")
except Exception:
    print("")
PYJ
}
ROOT=""
[[ -f "$CFG" ]] && ROOT="$(json_get "$CFG" path)"
[[ -z "$ROOT" && -f "$LEGACY_CFG" ]] && ROOT="$(json_get "$LEGACY_CFG" path)"
[[ -n "$ROOT" ]] || ROOT="/srv/hyper-cs16/servers/${SID}"
CSTRIKE="$ROOT/cstrike"
AMXX="$CSTRIKE/addons/amxmodx"
PLUGINS="$AMXX/configs/plugins.ini"
[[ -d "$CSTRIKE" ]] || fail "cstrike not found: $CSTRIKE"

echo "[INFO] Root: $ROOT"

# ------------------------------------------------------------
# 1. Extract embedded patch payload
# ------------------------------------------------------------
echo "[1/9] Extracting patch payload..."
cat > "$WORK/payload.b64" <<'PAYLOAD'

PAYLOAD
base64 -d "$WORK/payload.b64" > "$WORK/payload.tar.gz"
rm -f "$WORK/payload.b64"
mkdir -p "$WORK/payload"
tar -xzf "$WORK/payload.tar.gz" -C "$WORK/payload"

# ------------------------------------------------------------
# 2. Backup only touched live files
# ------------------------------------------------------------
echo "[2/9] Backing up current working runtime..."
mkdir -p "$BACKUP/files"
for src in "$WORK/payload/server/addons/amxmodx/scripting"/*.sma; do
  bn="$(basename "$src")"
  [[ -f "$AMXX/scripting/$bn" ]] && cp -a "$AMXX/scripting/$bn" "$BACKUP/files/$bn.sma"
  amxx="${bn%.sma}.amxx"
  [[ -f "$AMXX/plugins/$amxx" ]] && cp -a "$AMXX/plugins/$amxx" "$BACKUP/files/$amxx"
done
[[ -f "$PLUGINS" ]] && cp -a "$PLUGINS" "$BACKUP/plugins.ini"

# ------------------------------------------------------------
# 3. Download official compiler and compile in staging
#    Correct fix for the previous 'amxxpc32.so not found' error:
#    LD_LIBRARY_PATH points to the compiler directory.
# ------------------------------------------------------------
echo "[3/9] Preparing AMXX 1.9.0.5303 compiler..."
COMPILER_ROOT="$WORK/amxx5303"
mkdir -p "$COMPILER_ROOT"
TGZ="$WORK/amxx5303.tar.gz"
URL="https://www.amxmodx.org/amxxdrop/1.9/amxmodx-1.9.0-git5303-base-linux.tar.gz"
curl -fL --retry 3 --connect-timeout 15 "$URL" -o "$TGZ"
tar -xzf "$TGZ" -C "$COMPILER_ROOT"
COMPILER="$COMPILER_ROOT/addons/amxmodx/scripting/amxxpc"
COMPILER_LIB="$COMPILER_ROOT/addons/amxmodx/scripting"
OFFICIAL_INC="$COMPILER_ROOT/addons/amxmodx/scripting/include"
LIVE_INC="$AMXX/scripting/include"
chmod +x "$COMPILER" || true
[[ -x "$COMPILER" ]] || fail "official amxxpc missing"
[[ -f "$COMPILER_LIB/amxxpc32.so" ]] || fail "amxxpc32.so missing in official package"

ulimit -s unlimited || true
mkdir -p "$WORK/compiled"

compile_one() {
  local src="$1" bn out log rc
  bn="$(basename "$src")"
  out="$WORK/compiled/${bn%.sma}.amxx"
  log="$WORK/${bn}.log"
  echo "[AMXX] $bn"
  set +e
  (
    cd "$COMPILER_LIB"
    env LD_LIBRARY_PATH="$COMPILER_LIB${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}" \
      "$COMPILER" "$src" "-i$LIVE_INC" "-i$OFFICIAL_INC" "-o$out"
  ) >"$log" 2>&1
  rc=$?
  set -e
  if [[ $rc -ne 0 || ! -s "$out" ]]; then
    echo "[COMPILE FAILED] $bn rc=$rc"
    tail -n 80 "$log" || true
    return 1
  fi
  echo "[OK] ${bn%.sma}.amxx"
}

CRITICAL=(
  admin_loader.sma
  zmpl.sma
  zm_addon_knife.sma
  oldz_delux_menu.sma
  oldz_delux_hook.sma
  oldz_zclass_desperado_delux.sma
  oldz_account_privileges.sma
  oldz_store_models.sma
  oldz_store_sql.sma
  oldz_store_sync.sma
  oldz_chat_tags.sma
  oldz_credits_sql.sma
  oldz_level_system.sma
  oldz_top_stats.sma
)

for bn in "${CRITICAL[@]}"; do
  src="$WORK/payload/server/addons/amxmodx/scripting/$bn"
  [[ -f "$src" ]] || fail "payload source missing: $bn"
  if ! compile_one "$src"; then
    echo "[ABORT] Live server was NOT modified. Backup: $BACKUP"
    exit 20
  fi
done

# ------------------------------------------------------------
# 4. Deploy sources, compiled plugins and assets
# ------------------------------------------------------------
echo "[4/9] Installing DELUX/identity plugins..."
cp -a "$WORK/payload/server/addons/amxmodx/scripting/." "$AMXX/scripting/"
cp -a "$WORK/compiled/." "$AMXX/plugins/"

for d in models sound sprites; do
  if [[ -d "$WORK/payload/server/$d" ]]; then
    mkdir -p "$CSTRIKE/$d"
    cp -a "$WORK/payload/server/$d/." "$CSTRIKE/$d/"
  fi
done

chown -R cs16:www-data "$AMXX/plugins" "$AMXX/scripting" 2>/dev/null || true
chmod 0644 "$AMXX/plugins"/*.amxx 2>/dev/null || true

# ------------------------------------------------------------
# 5. Activate correct plugins; keep heavy DELUX weapons disabled
# ------------------------------------------------------------
echo "[5/9] Updating plugins.ini..."
python3 - "$PLUGINS" "$AMXX/plugins" <<'PYP'
from pathlib import Path
import sys
p=Path(sys.argv[1]); plugdir=Path(sys.argv[2])
lines=p.read_text(encoding='utf-8',errors='ignore').splitlines() if p.exists() else []
required=[
 'admin_loader.amxx',
 'zmpl.amxx',
 'zm_addon_knife.amxx',
 'oldz_account_privileges.amxx',
 'oldz_store_sql.amxx',
 'oldz_store_sync.amxx',
 'oldz_store_models.amxx',
 'oldz_chat_tags.amxx',
 'oldz_credits_sql.amxx',
 'oldz_level_system.amxx',
 'oldz_top_stats.amxx',
 'oldz_zclass_desperado_delux.amxx',
 'oldz_delux_menu.amxx',
 'oldz_delux_hook.amxx',
]
heavy={'oldz_delux_starchaser.amxx','oldz_delux_bloodmoon.amxx','oldz_delux_balrog95.amxx'}
reqset={x.lower() for x in required}
seen=set(); out=[]
for line in lines:
    raw=line.strip()
    token=raw.lstrip(';').strip().split(None,1)[0].lower() if raw else ''
    if token in heavy:
        out.append('; OLDZ-V8 disabled: 512-precache cleanup required: '+raw.lstrip(';').strip())
        continue
    if token in reqset:
        if token in seen: continue
        if (plugdir/token).exists():
            out.append(token)
            seen.add(token)
        continue
    if token=='zm_addon_knife_r8.amxx':
        out.append('; OLDZ-V8 duplicate knife plugin disabled: '+raw.lstrip(';').strip())
        continue
    out.append(line)

# Put missing required entries at the end in deterministic order.
for name in required:
    if name.lower() not in seen and (plugdir/name).exists():
        out.append(name)
        seen.add(name.lower())
p.write_text('\n'.join(out).rstrip()+'\n',encoding='utf-8')
PYP

# ------------------------------------------------------------
# 6. SQL helper patch if mysql CLI + sql.cfg credentials are available
# ------------------------------------------------------------
echo "[6/9] Applying identity SQL helper when possible..."
SQLPATCH="$WORK/payload/sql/oldz_delux_identity_v8.sql"
SQLCFG="$AMXX/configs/sql.cfg"
if command -v mysql >/dev/null 2>&1 && [[ -f "$SQLCFG" ]]; then
  read_cvar() { awk -v k="$1" '$1==k {gsub(/^"|"$/,"",$2); print $2; exit}' "$SQLCFG"; }
  DBH="$(read_cvar amx_sql_host)"; DBU="$(read_cvar amx_sql_user)"; DBP="$(read_cvar amx_sql_pass)"; DBN="$(read_cvar amx_sql_db)"
  if [[ -n "$DBH" && -n "$DBU" && -n "$DBN" ]]; then
    if MYSQL_PWD="$DBP" mysql -h "$DBH" -u "$DBU" "$DBN" < "$SQLPATCH"; then
      echo "[OK] SQL identity helper applied to $DBN"
    else
      echo "[WARN] SQL helper failed; server files remain installed. SQL file copied to $BACKUP/"
      cp -a "$SQLPATCH" "$BACKUP/"
    fi
  else
    cp -a "$SQLPATCH" "$BACKUP/"
    echo "[WARN] sql.cfg credentials incomplete; SQL patch saved to $BACKUP/"
  fi
else
  cp -a "$SQLPATCH" "$BACKUP/"
  echo "[WARN] mysql CLI/sql.cfg unavailable; SQL patch saved to $BACKUP/"
fi

# ------------------------------------------------------------
# 7. Website Linking.php: preserve both nickname and Steam history
# ------------------------------------------------------------
echo "[7/9] Updating website identity linker when site is found..."
if [[ -z "$SITE_ROOT" ]]; then
  mapfile -t CANDS < <(find /var/www /srv/www /home -maxdepth 6 -type f -path '*/lib/Linking.php' 2>/dev/null | head -n 10)
  if [[ ${#CANDS[@]} -eq 1 ]]; then SITE_ROOT="$(dirname "$(dirname "${CANDS[0]}")")"; fi
  if [[ ${#CANDS[@]} -gt 1 ]]; then
    for f in "${CANDS[@]}"; do
      if [[ "$f" == *old-zombie* ]]; then SITE_ROOT="$(dirname "$(dirname "$f")")"; break; fi
    done
  fi
fi
if [[ -n "$SITE_ROOT" && -f "$SITE_ROOT/lib/Linking.php" ]]; then
  mkdir -p "$BACKUP/site/lib"
  cp -a "$SITE_ROOT/lib/Linking.php" "$BACKUP/site/lib/Linking.php"
  cp -a "$WORK/payload/site/lib/Linking.php" "$SITE_ROOT/lib/Linking.php"
  php -l "$SITE_ROOT/lib/Linking.php" || fail "website Linking.php lint failed"
  echo "[OK] Site linker updated: $SITE_ROOT/lib/Linking.php"
else
  echo "[INFO] Site root not auto-detected. Site file is in archive: site/lib/Linking.php"
fi

# ------------------------------------------------------------
# 8. FastDL sync only new resources
# ------------------------------------------------------------
echo "[8/9] Syncing DELUX assets to FastDL..."
FD="/srv/hyper-cs16/fastdl/${SID}"
mkdir -p "$FD"
for d in models sound sprites; do
  if [[ -d "$WORK/payload/server/$d" ]]; then
    mkdir -p "$FD/$d"
    rsync -a "$WORK/payload/server/$d/" "$FD/$d/"
  fi
done
find "$FD" -type d -exec chmod 0755 {} + 2>/dev/null || true
find "$FD" -type f -exec chmod 0644 {} + 2>/dev/null || true

# Keep YaPB alive and do not touch Reunion/Metamod runtime.
if [[ -x "$CTL" ]]; then
  "$CTL" bots-enable "$SID" --quota "$QUOTA" --difficulty "$DIFF" >/dev/null 2>&1 || true
fi

# ------------------------------------------------------------
# 9. Restart + validate. Roll back plugins/config on boot failure.
# ------------------------------------------------------------
echo "[9/9] Restarting and validating..."
systemctl reset-failed "$UNIT" >/dev/null 2>&1 || true
systemctl restart "$UNIT" || true
sleep 10

if ! systemctl is-active --quiet "$UNIT"; then
  echo "[ERROR] Server did not stay active; rolling back touched AMXX binaries/config..."
  for f in "$BACKUP/files"/*.amxx; do [[ -f "$f" ]] && cp -a "$f" "$AMXX/plugins/$(basename "$f")"; done
  [[ -f "$BACKUP/plugins.ini" ]] && cp -a "$BACKUP/plugins.ini" "$PLUGINS"
  systemctl restart "$UNIT" || true
  journalctl -u "$UNIT" -n 160 --no-pager -o cat || true
  exit 30
fi

# Catch fatal precache/runtime errors after service reports active.
J="$WORK/journal.log"
journalctl -u "$UNIT" --since "2 minutes ago" --no-pager -o cat > "$J" || true
if grep -qiE 'FATAL ERROR|over the 512 limit|native .* was not found|Run time error 19' "$J"; then
  echo "[WARN] Serious AMXX/precache error detected after install:"
  grep -iE 'FATAL ERROR|over the 512 limit|native .* was not found|Run time error 19' "$J" | tail -n 40 || true
  echo "[ROLLBACK] Restoring AMXX binaries/plugin list."
  systemctl stop "$UNIT" || true
  for f in "$BACKUP/files"/*.amxx; do [[ -f "$f" ]] && cp -a "$f" "$AMXX/plugins/$(basename "$f")"; done
  [[ -f "$BACKUP/plugins.ini" ]] && cp -a "$BACKUP/plugins.ini" "$PLUGINS"
  systemctl restart "$UNIT" || true
  exit 31
fi

if [[ -x "$CTL" ]]; then
  echo
  echo "--- STATUS ---"
  "$CTL" status "$SID" || true
  echo
  echo "--- AMXX DELUX/IDENTITY ---"
  "$CTL" rcon "$SID" "amxx plugins" 2>/dev/null | grep -Ei 'DELUX|Account Privileges|SQL Credits|LEVEL|TOP|Admin Loader|Knife|Store' || true
fi

echo
echo "================================================================"
echo " [SUCCESS] DELUX + IDENTITY v8 installed"
echo "================================================================"
echo "DELUX: t+v"
echo "Menus: VIP / DELUX / ADMIN"
echo "Knife: Wolf Axe [DELUX]"
echo "Zombie: Desperado [DELUX] (+ ADMIN access)"
echo "Hook: bind q +dhook, 20/round"
echo "Model: Reega Imperator fallback; purchased model stays higher priority"
echo "Identity: same game nickname = same credits/level/top for Steam and Non-Steam"
echo "Privilege bridge: website-linked account mirrors VIP/DELUX flags on Steam and Non-Steam"
echo "Heavy DELUX weapon packs remain disabled to avoid the known GoldSrc 512 precache crash"
echo "Backup: $BACKUP"
